public class Main {
    static int compute() {
        try {
            System.out.println("In try block");
            return 10;
        } finally {
            System.out.println("Finally block always executes");
        }
    }

    public static void main(String[] args) {
        System.out.println("Result: " + compute());
    }
}

class InsufficientFundsException extends Exception {
    private final double amount;
    public InsufficientFundsException(double amount) {
        super("Short by: $" + amount);
        this.amount = amount;
    }
    public double getAmount() { return amount; }
}

public class Main {
    static void withdraw(double bal, double req) throws InsufficientFundsException {
        if (req > bal) throw new InsufficientFundsException(req - bal);
    }
    public static void main(String[] args) {
        try { withdraw(100.0, 150.0); }
        catch (InsufficientFundsException e) { System.out.println(e.getMessage()); }
    }
}

