public class Main {
    public static void main(String[] args) throws InterruptedException {
        Thread worker = new Thread(() -> {
            try { Thread.sleep(200); } catch (InterruptedException e) {}
            System.out.println("Worker completed task");
        });
        worker.start();
        System.out.println("Waiting for worker...");
        worker.join(); // Blocks calling thread until worker finishes
        System.out.println("All tasks finished");
    }
}

public class Main {
    public static void main(String[] args) {
        Thread daemon = new Thread(() -> {
            while (true) {
                System.out.println("Daemon heartbeating...");
                try { Thread.sleep(100); } catch (InterruptedException e) { break; }
            }
        });
        daemon.setDaemon(true); // Must be called before start()
        daemon.start();
        System.out.println("Main thread exiting");
        // JVM exits immediately when all user (non-daemon) threads finish
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Thread t = new Thread(() -> {
            try { Thread.sleep(100); } catch (InterruptedException e) {}
        });
        System.out.println("State 1: " + t.getState()); // NEW
        t.start();
        System.out.println("State 2: " + t.getState()); // RUNNABLE
        Thread.sleep(50);
        System.out.println("State 3: " + t.getState()); // TIMED_WAITING
        t.join();
        System.out.println("State 4: " + t.getState()); // TERMINATED
    }
}

