    public static void main(String[] args) {
        Runnable task = () -> {
            for (int i = 0; i < 3; i++) {
                System.out.println(Thread.currentThread().getName() + " yielding...");
                Thread.yield(); // Hint to OS scheduler that current thread is willing to yield CPU
            }
        };
        new Thread(task, "Worker-1").start();
        new Thread(task, "Worker-2").start();
    }
}

public class Main {
    public static void main(String[] args) {
        Thread t = new Thread(() -> {
            System.out.println("Thread running, testing flag...");
            // Thread.interrupted() returns status AND clears it
            // t.isInterrupted() returns status WITHOUT clearing it
            while (!Thread.currentThread().isInterrupted()) {
                // Cooperative work loop
            }
            System.out.println("Interrupted flag detected, exiting cleanly.");
        });
        t.start();
        t.interrupt();
    }
}

