public class Main {
    private final Object lock = new Object();
    private int counter = 0;

    public void increment() {
        synchronized (lock) { // Intrinsic monitor lock on dedicated private object
            counter++;
        }
    }

    public int getCounter() {
        synchronized (lock) {
            return counter;
        }
    }

    public static void main(String[] args) {
        Main m = new Main();
        m.increment();
        System.out.println("Counter: " + m.getCounter());
    }
}

public class Main {
    private static int globalCount = 0;
    private int instanceCount = 0;

    // Locks on Main.class Class object monitor
    public static synchronized void incGlobal() {
        globalCount++;
    }

    // Locks on 'this' instance monitor
    public synchronized void incInstance() {
        instanceCount++;
    }

    public static void main(String[] args) {
        Main.incGlobal();
        new Main().incInstance();
        System.out.println("Global: " + globalCount);
    }
}

public class Main {
    public static void main(String[] args) {
        Thread t1 = new Thread(() -> System.out.println("Low priority worker"));
        Thread t2 = new Thread(() -> System.out.println("High priority worker"));

        t1.setPriority(Thread.MIN_PRIORITY);  // Priority 1
        t2.setPriority(Thread.MAX_PRIORITY);  // Priority 10

        t1.start();
        t2.start();
        System.out.println("Norm priority: " + Thread.NORM_PRIORITY); // Priority 5
    }
}

